{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Viqualine, the closest analogue sharing the 6-methoxyquinoline and vinyl-substituted basic amine core, had an absolute oral bioavailability of 80% versus i.v. in healthy subjects (with F=0.73 in volunteers), directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Lenvatinib, a methoxyquinoline-containing drug, has an absolute bioavailability of about 85% in humans, supporting high oral absorption for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Alizapride, a basic heteroaromatic drug with a pyrrolidine amine, showed 72.5% absolute oral bioavailability, supporting high F for a similarly basic, moderately polar query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Tegaserod, a methoxyindole with a basic guanidine side chain, has only ~10% absolute bioavailability, but its different scaffold and extensive first-pass metabolism make this low-F evidence weakly transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue viqualine is experimentally high-F (73-80%) in humans, and other basic methoxyheteroaromatic drugs also show high oral bioavailability. The low-F tegaserod evidence is structurally distant and insufficient to outweigh the close analogue. Thus the query is predicted to have F >= 20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "The closest analogue differs by a rigid bicyclic amine and a benzylic hydroxyl group, which could alter absorption or first-pass metabolism.",
    "Human F data for the exact query are absent; extrapolation relies on structural analogy."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

